        en("ui.beep.voice.flash.jump", "Beep, voice, flash, and the jump when a bookmarked signature or named radio appears. If this is off, bookmarks stay, and Fieldwatch stays quiet.", LanguageSlot.BODY),
        en("ui.beep.watched.signature", "Beep on watched signature", LanguageSlot.CONTROL),
        en("ui.double.pip.media.volume", "A double pip on the media volume when a watched radio first appears, or comes back after leaving. It does not repeat while that radio stays in view. You can use the beep, the voice, or both. Turn the media volume up if you hear nothing, then tap Test alert.", LanguageSlot.BODY),
        en("ui.voice.watched.signature", "Voice on watched signature", LanguageSlot.CONTROL),
        en("ui.says.class.signature.same", "Says the class or the signature, on the same volume as the beep. A second hit is skipped if Fieldwatch is already speaking. With no speech engine, the beep still plays if Beep is on.", LanguageSlot.BODY),
        en("ui.what.say", "What to say", LanguageSlot.CONTROL),
        en("ui.class.group.live.such", "Class is the group on Live, such as finder tags or audio. Signature is the catalog name, such as Apple AirTags. Class + signature says both.", LanguageSlot.BODY),
        en("ui.test.alert", "Test alert", LanguageSlot.CONTROL),
        en("ui.jump.new.watched.detection", "Jump to new watched detection", LanguageSlot.CONTROL),
        en("ui.live.scrolls.new.watched", "Live scrolls to a new watched radio so you can see the flash. Needs the beep or the voice. Turn this off if you do not want the list to move.", LanguageSlot.BODY),
        en("ui.system.notification", "System notification", LanguageSlot.CONTROL),
        en("ui.silent.notification.when.watched", "A silent notification when a watched radio appears. The beep and the flash are enough for most sits.", LanguageSlot.BODY),
        en("ui.tag.detections.gps", "Tag detections with GPS", LanguageSlot.CONTROL),
        en("ui.stamps.phone.s.position", "Records where this phone was on {live}, {moving}, {places}, {debrief}, and new log rows. That is your position, not the other radio. The path stays empty without a high-accuracy fix. Heard-here TAK pins need this. Turn this off to keep your position out of the logs.", LanguageSlot.BODY),
        en("ui.places.label", "Places", LanguageSlot.CONTROL),
        en("ui.finder.tag.keeps.its", "A finder tag or Remote ID heard at two or more places in the last 7 days shows on its page and in the sit report. Each line is where this phone was. A return after a quiet stretch shows on its page. A Bluetooth radio that changes its address is skipped. Ordinary Wi-Fi stays off. Needs {gps}. There is no beep.", LanguageSlot.BODY),
        en("ui.online.place.names.maps", "Online place names and maps", LanguageSlot.CONTROL),
        en("ui.internet.debrief.places.turn", "Adds a street and city in Debrief and Places, and a map on the path. Nothing is sent to a Fieldwatch server. Offline, Debrief keeps the coordinates and the path uses pictures already saved. Turn this off to skip streets and the map.", LanguageSlot.BODY),
        en("ui.gnss.interference.check", "GNSS interference check", LanguageSlot.CONTROL),
        en("ui.detects.interference.spoofing.gnss", "Watches this phone’s GPS for a change that can mean interference. A router or other electronics next to the phone can cause the same change. Fieldwatch cannot tell the source or the distance.", LanguageSlot.BODY),
        en("ui.hit.opens.popup.after", "This turns the check on and off. It stays off until this phone is calibrated. A hit opens a popup, then a red line on Live until it ends. A hit already under way when the check starts can be missed.", LanguageSlot.BODY),
        en("ui.calibrate.phone.before.turning", "Calibrate this phone before the check will turn on.", LanguageSlot.BODY),
