        en("ui.sensitivity.label", "Sensitivity", LanguageSlot.CONTROL),
        en("ui.low.waits.deeper.drop", "Low waits for a deeper drop. High speaks up on a smaller drop, including a nearby router. Medium is the start.", LanguageSlot.BODY),
        en("ui.alert.label.2", "Warning level", LanguageSlot.CONTROL),
        en("ui.popup.red.line.beep", "The popup, the red line, the beep, and the voice start at this level. A weaker hit still shows in {diag} and in the sit report. Medium is the start.", LanguageSlot.BODY),
        en("ui.spoofing.checks", "Warn when the signal holds", LanguageSlot.CONTROL),
        en("ui.warns.when.gain.falls", "Warns when the receiver gain falls while the GPS signal holds. A clock or a position that does not match can raise that warning. One of those on its own does not warn. A careful fake signal can still get past this.", LanguageSlot.BODY),
        en("gnss.reach.note", "The popup and the red line still show if these are off. {beep} and {voice} on this page do not change the {watchlist} switches.", LanguageSlot.BODY),
